//! `changeFigure` 立绘身份判定的两个 WebGAL 口径。
//!
//! 4.6.3 及以前只比较图片地址，未写 `-left/-right` 时沿用旧基准；
//! 4.6.4 起位置(含默认 center)也参与判定，省略位置等于换到 center。

use std::path::PathBuf;

use webgal_video_export::{
    config::{ExportConfig, FigureSideMode},
    project::Project,
    script::{ChoicePolicy, compile},
};

fn plan(mode: FigureSideMode) -> webgal_video_export::plan::Plan {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/side");
    let project = Project::open(path).expect("open side fixture");
    let config = ExportConfig {
        figure_side: mode,
        ..ExportConfig::default()
    };
    let policy = ChoicePolicy::new(&config.choices);
    compile(&project, &config, &policy).expect("compile")
}

#[test]
fn legacy_keeps_previous_side_when_omitted() {
    let plan = plan(FigureSideMode::Legacy);
    let track = plan
        .figures
        .iter()
        .find(|track| track.id == "soyo")
        .expect("soyo track");
    assert_eq!(track.keys.len(), 2, "旧版省略位置不会新建立绘");
    // 第一次 -left：基准 -430，输出 1920 时缩放 0.75 → -323。
    assert_eq!(
        track.keys[0]
            .transform
            .position
            .and_then(|position| position.x),
        Some(-323)
    );
    // setTransform 500 仍然相对 -left 基准：(-430 + 500) × 0.75 = 52.5 → 53。
    assert_eq!(
        track.keys[1]
            .transform
            .position
            .and_then(|position| position.x),
        Some(53)
    );
    assert!(!track.keys[1].snap_transform, "同一立绘的位移要插值");
}

#[test]
fn modern_treats_omitted_side_as_center() {
    let plan = plan(FigureSideMode::Modern);
    let track = plan
        .figures
        .iter()
        .find(|track| track.id == "soyo")
        .expect("soyo track");
    assert_eq!(track.keys.len(), 3, "4.6.4 会在省略位置时重建立绘");
    let key = track.keys.last().expect("center key");
    assert_eq!(
        key.transform.position.and_then(|position| position.x),
        Some(0),
        "省略 -left 等于 center"
    );
    assert!(key.snap_transform, "身份变化后直接落到目标变换");
    assert!(key.figure_switch, "旧立绘需要退场过渡");
    assert_eq!(key.t_us, 100_000, "wait:100 之后才发生第二次 changeFigure");
}

#[test]
fn auto_without_engine_manifest_falls_back_to_legacy() {
    let plan = plan(FigureSideMode::Auto);
    let track = plan
        .figures
        .iter()
        .find(|track| track.id == "soyo")
        .expect("soyo track");
    assert_eq!(track.keys.len(), 2, "fixture 没有 webgal-engine.json");
}
